def candidate(pin,records,expected_digest):
    pin=subprocess.check_output(['git','rev-parse',pin+'^{commit}'],cwd=ROOT,text=True).strip()
    archive=subprocess.check_output(['git','archive',pin],cwd=ROOT)
    with tempfile.TemporaryDirectory(prefix='c6-ai-tactical-') as tmp:
        tmp=Path(tmp);source=tmp/'source';source.mkdir()
        subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
        if (source/'tools/linux/player_ai_tactical_audit.py').read_bytes()!=Path(__file__).read_bytes():raise ValueError('driver not committed at pin')
        # Gate every archived regular source against its immutable Git content,
        # before and after all builds. Build artifacts are outside this set.
        paths=subprocess.check_output(['git','ls-tree','-r','--name-only',pin],cwd=ROOT,text=True).splitlines()
        identities={}
        for path in paths:
            p=source/path
            if p.is_symlink():continue
            expected=subprocess.check_output(['git','show',pin+':'+path],cwd=ROOT)
            if p.read_bytes()!=expected:raise ValueError('archive source mismatch '+path)
            identities[path]=sha(expected)
        if 'pub mod player_ai_tactical;' not in (source/'crates/c6-core/src/lib.rs').read_text():raise ValueError('missing committed Tactical export')
        tests=subprocess.check_output(['cargo','test','--offline','-p','c6-core','player_ai_tactical'],cwd=source,text=True)
        if 'test player_ai_tactical::tests::boundaries ... ok' not in tests:raise ValueError('actual Tactical source test not run')
        subprocess.run(['cargo','clippy','--offline','-p','c6-core','--all-targets','--','-D','warnings'],cwd=source,check=True)
        subprocess.run(['cargo','build','--offline','--release','-p','c6-core'],cwd=source,check=True)
        (tmp/'main.rs').write_text(HARNESS)
        subprocess.run(['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'main.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps'),'-o',str(tmp/'candidate')],check=True)
        (tmp/'records').write_bytes(records)
